WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE t.production_year=2008),
mc_counts AS MATERIALIZED (SELECT mc.movie_id, COUNT(*)::HUGEINT AS n FROM movie_companies mc JOIN selected_titles eligible ON eligible.id=mc.movie_id WHERE TRUE GROUP BY mc.movie_id)
SELECT COALESCE(SUM(mc.n),0) FROM selected_titles t JOIN mc_counts mc ON mc.movie_id=t.id;

WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE t.production_year=1962),
mi_idx_counts AS MATERIALIZED (SELECT mi_idx.movie_id, COUNT(*)::HUGEINT AS n FROM movie_info_idx mi_idx JOIN selected_titles eligible ON eligible.id=mi_idx.movie_id WHERE mi_idx.info_type_id=99 GROUP BY mi_idx.movie_id)
SELECT COALESCE(SUM(mi_idx.n),0) FROM selected_titles t JOIN mi_idx_counts mi_idx ON mi_idx.movie_id=t.id;
